import { useMemo, type ReactNode } from 'react';
import { useIntl } from 'react-intl';

import { getTextFromNode } from '../../../filters/filter/utils/getTextFromNode.js';
import {
  _formatTimeValue,
  _formatTimeframe,
  _getFormattedTimeValue,
  _parseValue,
} from '../../forms-core/time/timeParser.js';
import type { TimeframeSelectorPresetItemProps } from '../Item.js';

//#region Typings
interface UseItemValues {
  timeframeDisplayValue: ReactNode;
  tooltipFormattedTimeValueStart: string;
  tooltipFormattedTimeValueEnd: string;
  formattedPresetItemValue: string;
  isAbsoluteTimeframe: boolean;
  isInvalid: boolean;
}
//#endregion

/** Hook used to retrieve the formatted values shown in the PresetItem. */
export function useItemFormatting(
  value: TimeframeSelectorPresetItemProps['value'],
  children?: ReactNode,
  precision?: 'minutes' | 'seconds' | 'milliseconds',
): UseItemValues {
  const intl = useIntl();
  const { from, to } = _parseValue(value, true);
  const isAbsoluteTimeframe =
    from?.type === 'iso8601' && to?.type === 'iso8601';

  const startTime = intl.formatMessage({
    defaultMessage: 'Start',
    id: 'QF4myF79Hrp3e/0Q',
    description:
      'Description for the start time of the preset item value, that is shown in the tooltip',
  });

  const endTime = intl.formatMessage({
    defaultMessage: 'End',
    id: 'fHGjouAXIpSTl8T2',
    description:
      'Description for the end time of the preset item value, that is shown in the tooltip',
  });

  const tooltipFormattedTimeValueStart = useMemo(
    () => `${startTime}: ${_getFormattedTimeValue(from, precision)}`,
    [from, precision, startTime],
  );

  const tooltipFormattedTimeValueEnd = useMemo(
    () => `${endTime}: ${_getFormattedTimeValue(to, precision)}`,
    [endTime, precision, to],
  );

  const formattedPresetItemValue = useMemo(
    () =>
      `${_formatTimeValue(value.from, precision)} → ${_formatTimeValue(
        value.to,
        precision,
      )}`,
    [precision, value.from, value.to],
  );

  const { displayValue, isInvalid } = useMemo(
    () => _formatTimeframe(value, intl, precision),
    [intl, precision, value],
  );

  const timeframeDisplayValue = useMemo(
    () => getTextFromNode(children, intl, '') || displayValue,
    [children, displayValue, intl],
  );

  return {
    timeframeDisplayValue,
    tooltipFormattedTimeValueStart,
    tooltipFormattedTimeValueEnd,
    formattedPresetItemValue,
    isAbsoluteTimeframe,
    isInvalid,
  };
}
